javascript.code:
const grid = document.getElementById('god-grid');
const nameEl = document.getElementById('detail-name');
const domainEl = document.getElementById('detail-domain');
const factEl = document.getElementById('detail-fact');
DATA.gods.forEach(g => {
  const card = document.createElement('article');
  card.className = 'god-card';
  card.innerHTML = '<div class="medal">' + g.glyph + '</div><h3>' + g.name + '</h3><p>' + g.domain + '</p>';
  card.addEventListener('click', () => {
    nameEl.textContent = g.name;
    domainEl.textContent = g.domain;
    factEl.textContent = g.fact;
    document.getElementById('god-detail').style.borderLeftColor = g.color;
  });
  grid.append(card);
});
document.getElementById('oracle-btn').addEventListener('click', () => {
  const msgs = DATA.oracle;
  document.getElementById('oracle-a').textContent = msgs[Math.floor(Math.random() * msgs.length)];
});

